look.customCSS:
/* ───── 午夜舞会 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/390px 520px repeat,radial-gradient(ellipse at 20% 85%,rgba(200,150,220,.45),transparent 55%),radial-gradient(ellipse at 85% 60%,rgba(140,170,240,.35),transparent 50%),linear-gradient(180deg,#3E3C8E 0%,#5A55B0 45%,#8C7CC8 80%,#B79AD6 100%) !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}
/* 聊天顶上那道光带和发光的钟：跟着内容滚，只在最上面 */
[data-wk="body"]{background:url("data:image/svg+xml;base64,") center top/100% auto no-repeat !important;background-attachment:local !important;padding-top:170px !important}

/* 顶栏底栏：悬浮的半透明紫胶囊，一圈淡金边 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:transparent !important;border-bottom:none !important;box-shadow:none !important;gap:6px !important;z-index:5 !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;left:12px !important;right:12px !important;top:calc(var(--app-safe-top, 0px) + 2px) !important;bottom:4px !important;background:linear-gradient(180deg,rgba(120,110,200,.55),rgba(90,85,176,.45)) !important;backdrop-filter:blur(10px) !important;-webkit-backdrop-filter:blur(10px) !important;border-radius:20px !important;box-shadow:inset 0 0 0 1.4px rgba(242,217,160,.75),0 8px 20px rgba(40,30,100,.3) !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.12em !important}
[data-wk="headdim"]{color:#D8D2F2 !important;white-space:nowrap !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#fff !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#fff !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-right:8px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]),[data-wk="chathead"] + *:not([data-wk="body"]) *{color:#fff !important}

/* 头像：一圈珍珠光环，右上一颗小星 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:50% !important;box-shadow:0 0 0 3px #FBF2DC,0 0 0 4px #D9B46A,0 0 16px 4px rgba(255,240,200,.45) !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:50% !important}
button[data-wk="avatar"]::after,span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;right:-4px !important;top:-6px !important;width:10px !important;height:13px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") center/contain no-repeat !important;pointer-events:none !important}

/* 他的话：珍珠白，淡淡的光；你的话：紫色薄玻璃，描一圈淡金 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:16px !important;letter-spacing:.08em !important;padding:11px 20px !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(120deg,#fff,#FFFDF6 50%,#FBF2DC) !important;color:#3F3A6A !important;border:1.2px solid rgba(242,217,160,.8) !important;box-shadow:0 0 14px rgba(255,245,220,.55) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,rgba(110,100,200,.75),rgba(80,72,170,.75)) !important;color:#fff !important;border:1.4px solid rgba(242,217,160,.85) !important;box-shadow:0 0 12px rgba(242,217,160,.25),inset 0 1px 0 rgba(255,255,255,.25) !important}

/* 时间：一行淡紫小字 */
[data-wk="time"] > span{background:transparent !important;border:none !important;box-shadow:none !important;color:#D8D2F2 !important;letter-spacing:.3em !important;font-size:11.5px !important}
/* 已读＝金色小钟；已送达＝淡紫空心小钟 */
[data-wk="meta"]{color:#D8D2F2 !important;font-size:10.5px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::after{content:"" !important;width:12px !important;height:12px !important;flex:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(242,217,160,.8)) !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFDF6 !important;border:1.2px solid rgba(242,217,160,.8) !important;border-radius:16px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#D9B46A !important}
[data-wk="name"]{color:#D8D2F2 !important}

/* 动描：没有框，淡金斜体，上下各一颗小星 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{position:relative !important;display:block !important;background:transparent !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#FFF0CC !important;font-style:italic !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.1em !important;text-align:center !important;text-shadow:0 0 8px rgba(255,230,170,.5) !important;padding:14px 26px !important}
[data-wk="narrink"]::before,[data-wk="narrink"]::after{content:"" !important;position:absolute !important;left:50% !important;width:8px !important;height:11px !important;margin-left:-4px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="narrink"]::before{top:0 !important}
[data-wk="narrink"]::after{bottom:0 !important}
/* 系统提示 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{border:none !important;color:#D8D2F2 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important;padding-left:16px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") left center/8px 11px no-repeat !important}
[data-wk="sysnoteclose"]{color:#D8D2F2 !important}

/* 底栏：同一种悬浮胶囊；输入框淡紫玻璃；发送细线箭头；最右「让他回复」是发光珍珠钮 */
[data-wk="composer"]{position:relative !important;overflow:visible !important;background:transparent !important;border-top:none !important;box-shadow:none !important;align-items:center !important;gap:10px !important;padding-left:24px !important;padding-right:24px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:12px !important;right:12px !important;top:6px !important;bottom:6px !important;background:linear-gradient(180deg,rgba(120,110,200,.55),rgba(90,85,176,.45)) !important;backdrop-filter:blur(10px) !important;-webkit-backdrop-filter:blur(10px) !important;border-radius:20px !important;box-shadow:inset 0 0 0 1.4px rgba(242,217,160,.75),0 8px 20px rgba(40,30,100,.3) !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="chatinput"]{background:rgba(255,255,255,.12) !important;border:1px solid rgba(216,210,242,.55) !important;border-radius:14px !important;color:#fff !important;letter-spacing:.08em !important}
[data-wk="chatinput"]::placeholder{color:#D8D2F2 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:48px !important;min-width:48px !important;height:48px !important;border-radius:50% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 10px rgba(255,236,190,.8)) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:rgba(70,64,150,.95) !important;border-top:1px solid rgba(242,217,160,.6) !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}
/* ───── 王宫台阶：连发一级级错开（他往右、你往左），贴紧，每级底下一道淡金立面；最新那段最后一级落一只玻璃鞋 ───── */
[data-wk="msg"][data-first="0"]{margin-top:-6px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{border-radius:6px !important;box-shadow:0 5px 0 rgba(217,180,106,.75),0 0 14px rgba(255,245,220,.5) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{border-radius:6px !important;box-shadow:0 5px 0 rgba(60,52,140,.85),inset 0 1px 0 rgba(255,255,255,.25),0 0 12px rgba(242,217,160,.2) !important}
[data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"],[data-wk="msg"][data-me="0"][data-first="0"] [data-wk="meta"]{margin-left:20px !important}
[data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"]{max-width:calc(100% - 20px) !important}
[data-wk="msg"][data-me="1"][data-first="0"] [data-wk="bubble"]{margin-right:20px !important;max-width:calc(100% - 20px) !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"],[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="meta"]{margin-left:40px !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"]{max-width:calc(100% - 40px) !important}
[data-wk="msg"][data-me="1"][data-first="0"] + [data-wk="msg"][data-me="1"][data-first="0"] [data-wk="bubble"]{margin-right:40px !important;max-width:calc(100% - 40px) !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"],[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="meta"]{margin-left:60px !important}
[data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] + [data-wk="msg"][data-me="0"][data-first="0"] [data-wk="bubble"]{max-width:calc(100% - 60px) !important}
[data-wk="msg"][data-me="1"][data-first="0"] + [data-wk="msg"][data-me="1"][data-first="0"] + [data-wk="msg"][data-me="1"][data-first="0"] [data-wk="bubble"]{margin-right:60px !important;max-width:calc(100% - 60px) !important}
[data-wk="meta"]{margin-top:9px !important}
[data-wk="msg"][data-me="0"][data-last="1"]:not(:has(~ [data-wk="msg"][data-me="0"])) [data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;right:-52px !important;bottom:-6px !important;width:44px !important;height:28px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 6px rgba(220,235,255,.9)) !important}
/* ───── 梦幻感放进气泡（她 2026-11-13 的五条） ───── */
/* 4. 星星：去掉满屏平铺的星和光点，只在两侧空白处留六颗；头像上的小星也拿掉 */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") left 10px top 18%/10px 14px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") right 12px top 34%/8px 11px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") left 14px top 52%/8px 11px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") right 10px top 66%/10px 14px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") left 8px top 80%/7px 10px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") right 16px top 88%/7px 10px no-repeat,radial-gradient(ellipse at 20% 85%,rgba(200,150,220,.45),transparent 55%),radial-gradient(ellipse at 85% 60%,rgba(140,170,240,.35),transparent 50%),linear-gradient(180deg,#3E3C8E 0%,#5A55B0 45%,#8C7CC8 80%,#B79AD6 100%) !important}
button[data-wk="avatar"]::after,span[data-wk="avatar"]:not([data-halo])::after{content:none !important}
/* 1. 他的台阶：顶面是很淡的珠光渐变（白里带一点粉和蓝），底下垫一圈暖光 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(135deg,#FFFFFF 0%,#FCEFF5 35%,#EEF1FF 70%,#FFF7E8 100%) !important;box-shadow:inset 0 1px 0 #fff,0 5px 0 rgba(217,180,106,.8),0 6px 22px rgba(255,210,160,.5) !important}
/* 2. 我的台阶：半透明亮一档的紫，磨砂，顶边一道细金线 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,rgba(170,160,240,.55),rgba(135,125,225,.45)) !important;backdrop-filter:blur(6px) !important;-webkit-backdrop-filter:blur(6px) !important;border:1px solid rgba(242,217,160,.55) !important;box-shadow:inset 0 1.6px 0 rgba(255,236,190,.95),0 5px 0 rgba(70,60,160,.75),0 6px 18px rgba(200,190,255,.3) !important}
/* 3. 台阶贴紧：组内零间距，上一级的立面直接压着下一级 */
[data-wk="msg"][data-first="0"]{margin-top:-12px !important}
[data-wk="msg"][data-first="0"] [data-wk="row"]{padding-top:0 !important;margin-top:0 !important}
/* 5. 状态字：近白，大一号 */
[data-wk="meta"]{color:#E6E2FA !important;font-size:11.5px !important}
/* ───── 头像框：南瓜马车的小窗（头像从窗里探出来） ───── */
button[data-wk="avatar"],span[data-wk="avatar"]{box-shadow:none !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:-47% !important;right:-47% !important;top:-63% !important;bottom:-61% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;border:none !important;border-radius:0 !important;z-index:2 !important;filter:drop-shadow(0 0 8px rgba(255,230,180,.55)) !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before,[data-wk="statehead"] [data-wk="avatar"]::before{content:none !important}
[data-wk="chathead"] img[data-wk="avatar"],[data-wk="chathead"] [data-wk="avatar"]{box-shadow:0 0 0 2.5px #FBF2DC,0 0 0 3.5px #D9B46A !important}
/* 头像框比头像大，给台阶让一点位置 */
[data-wk="msg"] [data-wk="row"]{gap:14px !important}
/* 顶栏不做框：底子透明，底下一条横贯全宽的细金线（两头淡出），正中一颗小星 */
[data-wk="chathead"]::before{content:none !important}
[data-wk="chathead"]{background:linear-gradient(180deg,rgba(62,60,142,.55),rgba(62,60,142,0)) !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:0 !important;height:12px !important;margin-bottom:-6px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI0ZGRjZEQScvPjwvc3ZnPg==") center/8px 11px no-repeat,linear-gradient(90deg,rgba(242,217,160,0),rgba(242,217,160,.85) 20%,rgba(242,217,160,.85) calc(50% - 10px),transparent calc(50% - 10px),transparent calc(50% + 10px),rgba(242,217,160,.85) calc(50% + 10px),rgba(242,217,160,.85) 80%,rgba(242,217,160,0)) center/100% 1px no-repeat !important;pointer-events:none !important}
[data-wk="chatmore"]{margin-right:0 !important}
/* 底栏也不做框：透明底往下晕一点深紫，上沿一条横贯的细金线、正中一颗星 */
